                url.set("https://www.mozilla.org/MPL/2.0/")
                distribution.set("repo")
                comments.set("The uniffi crates, compiled unmodified into libmasko_player_ffi.so; see THIRD_PARTY_NOTICES.md.")
            }
            license {
                name.set("Third-party notices")
